sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.cah-hero {
  min-height: 600px;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: #181818;
  font-family: 'Poppins', 'Inter', -apple-system, sans-serif;
  position: relative;
  overflow: hidden;
}

/* Subtle decorative blur blob */
.cah-hero::before {
  content: "";
  position: absolute;
  top: -100px;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 400px;
  background: radial-gradient(circle, rgba(83,186,0,0.08) 0%, rgba(24,24,24,0) 70%);
  z-index: 0;
  pointer-events: none;
}

.hero-content {
  max-width: 900px;
  padding: 80px 20px;
  z-index: 1;
  position: relative;
}

.hero-badge {
  display: inline-block;
  padding: 8px 18px;
  margin-bottom: 24px;
  background: #1F1F1F;
  color: #53BA00;
  border: 1px solid rgba(83,186,0,0.2);
  border-radius: 9999px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.5px;
  box-shadow: 0 2px 8px rgba(83, 186, 0, 0.1);
}

.hero-content h1 {
  margin: 0;
  color: #FFFFFF;
  font-size: 64px;
  font-weight: 800;
  letter-spacing: -1.5px;
  line-height: 1.1;
}

.hero-content h1 span {
  display: block;
  color: #53BA00;
}

.hero-content p {
  max-width: 680px;
  margin: 32px auto;
  color: #B0B0B0;
  font-size: 20px;
  font-weight: 400;
  line-height: 1.6;
}

.hero-buttons {
  display: flex;
  justify-content: center;
  gap: 20px;
  margin-top: 40px;
}

.hero-buttons button {
  border: none;
  padding: 16px 32px;
  border-radius: 12px;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  display: flex;
  align-items: center;
  gap: 8px;
}

.hero-buttons button .glyphicon {
  font-size: 14px;
}

.hero-buttons .primary-btn {
  background: #53BA00;
  color: #FFFFFF;
  box-shadow: 0 4px 12px rgba(83, 186, 0, 0.2);
}

.hero-buttons .primary-btn:hover {
  background: #479e00;
  transform: translateY(-2px);
  box-shadow: 0 8px 16px rgba(83, 186, 0, 0.3);
}

.hero-buttons .secondary-btn {
  background: transparent;
  color: #FFFFFF;
  border: 1px solid rgba(255,255,255,0.2);
}

.hero-buttons .secondary-btn:hover {
  background: #1F1F1F;
  border-color: #53BA00;
  color: #53BA00;
  transform: translateY(-2px);
}

.hero-users {
  margin-top: 40px;
  color: #B0B0B0;
  font-size: 14px;
  font-weight: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

.hero-users span {
  color: #53BA00;
}

@media (max-width: 768px) {
  .hero-content h1 {
    font-size: 42px;
  }
  .hero-buttons {
    flex-direction: column;
    width: 100%;
  }
  .hero-buttons button {
    width: 100%;
    justify-content: center;
  }
}
